def compute(vars):
    american_personnel = vars["v1"]
    us_airways_personnel = vars["v2"]

    if us_airways_personnel == 0:
        return None

    ratio = american_personnel / us_airways_personnel

    return {
        "value": ratio,
        "trace": {
            "american_personnel": american_personnel,
            "us_airways_personnel": us_airways_personnel,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
